#define ROL(x, n) ((((n) & 31) ? (((x) << ((n) & 31)) | ((x) >> (32 - ((n) & 31)))) : (x)))
static u32 p0(u32 x) { return x ^ ROL(x, 9) ^ ROL(x, 17); }
static u32 p1(u32 x) { return x ^ ROL(x, 15) ^ ROL(x, 23); }
static u32 ff(int j, u32 x, u32 y, u32 z) { return j < 16 ? x ^ y ^ z : (x & y) | (x & z) | (y & z); }
static u32 gg(int j, u32 x, u32 y, u32 z) { return j < 16 ? x ^ y ^ z : (x & y) | (~x & z); }
static u32 be32(const u8 *p) { return (u32)p[0] << 24 | (u32)p[1] << 16 | (u32)p[2] << 8 | p[3]; }

