static const u32 DIGEST1[8] = {0x66c7f0f4U, 0x62eeedd9U, 0xd1f2d46bU, 0xdc10e4e2U, 0x4167c487U, 0x5cf2f7a2U, 0x297da02bU, 0x8f4ba8e0U};
static const u32 DIGEST2[8] = {0xdebe9ff9U, 0x2275b8a1U, 0x38604889U, 0xc18e5a4dU, 0x6fdb70e5U, 0x387e5765U, 0x293dcba3U, 0x9c0c5732U};

struct trace { u32 W[68], WP[64], st[64][8]; };
// CF(V, ME(B)) with the expansion and per-round registers recorded in tr.
static void compress(u32 v[8], const u8 *blk, struct trace *tr) {
    u32 *W = tr->W, *WP = tr->WP;
    for (int j = 0; j < 16; j++) W[j] = be32(blk + 4 * j);
    for (int j = 16; j < 68; j++) W[j] = p1(W[j - 16] ^ W[j - 9] ^ ROL(W[j - 3], 15)) ^ ROL(W[j - 13], 7) ^ W[j - 6];
    for (int j = 0; j < 64; j++) WP[j] = W[j] ^ W[j + 4];
    u32 A = v[0], B = v[1], C = v[2], D = v[3], E = v[4], F = v[5], G = v[6], H = v[7];
    for (int j = 0; j < 64; j++) {
        u32 Tj = j < 16 ? 0x79cc4519U : SM3_T2;
        u32 ss1 = ROL(ROL(A, 12) + E + ROL(Tj, j), 7);
        u32 ss2 = ss1 ^ ROL(A, 12);
        u32 tt1 = ff(j, A, B, C) + D + ss2 + WP[j];
        u32 tt2 = gg(j, E, F, G) + H + ss1 + W[j];
        D = C; C = ROL(B, 9); B = A; A = tt1; H = G; G = ROL(F, 19); F = E; E = p0(tt2);
        u32 *s = tr->st[j]; s[0] = A; s[1] = B; s[2] = C; s[3] = D; s[4] = E; s[5] = F; s[6] = G; s[7] = H;
    }
    u32 r[8] = {A, B, C, D, E, F, G, H};
    for (int i = 0; i < 8; i++) v[i] ^= r[i];
}
// Padding: 1 bit, zeros to 448 mod 512, 64-bit big-endian bit length. Returns number of blocks written to out (max 2 here).
static int pad(const u8 *m, int len, u8 out[128]) {
    int n = 0; for (int i = 0; i < len; i++) out[n++] = m[i];
    out[n++] = 0x80; while ((n % 64) != 56) out[n++] = 0;
    u64 bits = (u64)len * 8; for (int i = 7; i >= 0; i--) out[n++] = (u8)(bits >> (8 * i));
    return n / 64;
}
static int cmp8(const u32 *a, const u32 *b) { for (int i = 0; i < 8; i++) if (a[i] != b[i]) return 0; return 1; }
// Hash message m, comparing each block's trace with the published values. Returns the number of matching published values.
static int example(const char *name, const u8 *m, int len, const u32 *const *Wp, const u32 *const *WPp, const u32 (*const *STp)[8], const u32 *digest, const u32 *v1, int nblocks) {
    u8 padded[128]; static struct trace tr; u32 v[8]; int good = 0;
    int nb = pad(m, len, padded);
    if (nb != nblocks) { pstr("FAIL padding block count\n"); return 0; }
    for (int i = 0; i < 8; i++) v[i] = IV[i];
    for (int b = 0; b < nb; b++) {
        compress(v, padded + 64 * b, &tr);
        int w = 0, wp = 0, st = 0;
        for (int j = 0; j < 68; j++) w += tr.W[j] == Wp[b][j];
        for (int j = 0; j < 64; j++) wp += tr.WP[j] == WPp[b][j];
        for (int j = 0; j < 64; j++) st += cmp8(tr.st[j], STp[b][j]);
        good += w + wp + st;
        pstr(w == 68 && wp == 64 && st == 64 ? "PASS " : "FAIL "); pstr(name); pstr(" block "); pdec(b + 1);
        pstr(": W "); pdec(w); pstr("/68, W' "); pdec(wp); pstr("/64, round states "); pdec(st); pstr("/64\n");
        if (b + 1 < nb) { int ok = cmp8(v, v1); good += ok; pstr(ok ? "PASS " : "FAIL "); pstr(name); pstr(" chaining value V_1\n"); }
    }
    int ok = cmp8(v, digest); good += ok;
    pstr(ok ? "PASS " : "FAIL "); pstr(name); pstr(" digest: ");
    for (int i = 0; i < 8; i++) { phex(v[i], 8); if (i < 7) pstr(" "); }
    pstr("\n");
    return good;
}
int paper_main(void) {
    static const u8 m1[3] = {0x61, 0x62, 0x63};
    u8 m2[64]; for (int i = 0; i < 64; i++) m2[i] = (u8)('a' + (i % 4));
    static const u32 *const W1[1] = {EX1_W}; static const u32 *const WP1[1] = {EX1_WP};
    static const u32 (*const ST1[1])[8] = {EX1_ST};
    static const u32 *const W2[2] = {EX2A_W, EX2B_W}; static const u32 *const WP2[2] = {EX2A_WP, EX2B_WP};
    static const u32 (*const ST2[2])[8] = {EX2A_ST, EX2B_ST};
    int good = 0;
    good += example("example 1 (abc)", m1, 3, W1, WP1, ST1, DIGEST1, 0, 1);
    good += example("example 2 (abcd x16)", m2, 64, W2, WP2, ST2, DIGEST2, EX2B_IN, 2);
    pstr("total: "); pdec(good); pstr(" of 591 match\n");
    pstr(good == 591 ? "PASS\n" : "FAIL\n");
    return good == 591 ? 0 : 1;
}
